//! The implementation file of a component: everything that calls into the
//! scaffolding.

use std::fmt::Write;

use uniffi_bindgen::interface::AsType;

use super::calls::Receiver;
use super::types::Gen;

impl Gen<'_> {
    pub(crate) fn emit_source(&self, header_name: &str) -> String {
        let mut out = String::new();
        let _ = writeln!(
            out,
            "/* This file was autogenerated by uniffi-bindgen-c. Do not edit it by hand. */\n"
        );
        let _ = writeln!(out, "#include \"{header_name}\"\n");
        out.push_str(&self.emit_ffi_declarations());
        out.push_str(&self.emit_helpers());
        if self.has_async_callbacks() {
            out.push_str("static void uniffi_foreign_future_dropped(uint64_t handle) {\n    (void)handle;\n}\n\n");
        }
        for cb in self.ci.callback_interface_definitions() {
            out.push_str(&self.emit_handle_map(&self.local(cb.name()), false));
        }
        for obj in self.ci.object_definitions() {
            if obj.has_callback_interface() {
                out.push_str(&self.emit_handle_map(&self.local(obj.name()), true));
            }
        }
        out.push_str(&self.emit_codec_prototypes());
        for cb in self.ci.callback_interface_definitions() {
            out.push_str(&self.emit_callback_vtable(
                &self.local(cb.name()),
                &cb.vtable_methods(),
                cb.ffi_init_callback().name(),
                &self.ffi_type(&cb.vtable()),
            ));
        }
        for obj in self.ci.object_definitions() {
            if obj.has_callback_interface()
                && let Some(vtable) = obj.vtable()
            {
                out.push_str(&self.emit_callback_vtable(
                    &self.local(obj.name()),
                    &obj.vtable_methods(),
                    obj.ffi_init_callback().name(),
                    &self.ffi_type(&vtable),
                ));
            }
        }
        out.push_str(&self.emit_ensure_init());
        out.push_str(&self.emit_codecs());
        out.push_str(&self.emit_error_lifters());
        for cb in self.ci.callback_interface_definitions() {
            out.push_str(&self.emit_callback_lift_lower(&self.local(cb.name())));
        }
        for obj in self.ci.object_definitions() {
            out.push_str(&self.emit_object(obj));
        }
        for r in self.ci.record_definitions() {
            out.push_str(&self.emit_value_methods(
                &r.as_type(),
                r.constructors(),
                r.methods(),
                &r.uniffi_trait_methods(),
            ));
        }
        for e in self.ci.enum_definitions() {
            out.push_str(&self.emit_value_methods(
                &e.as_type(),
                e.constructors(),
                e.methods(),
                &e.uniffi_trait_methods(),
            ));
        }
        for f in self.ci.function_definitions() {
            let name = self.public(f.name());
            let _ = writeln!(
                out,
                "{} {{\n{}}}\n",
                self.signature(f, &name, None),
                self.call_body(f, &Receiver::None)
            );
            if f.is_async() {
                out.push_str(&self.async_variant(f, &name, None, &Receiver::None));
            }
        }
        out
    }

    /// Buffer plumbing and call-status handling, private to this file.
    fn emit_helpers(&self) -> String {
        let from_bytes = self.ci.ffi_rustbuffer_from_bytes();
        let free = self.ci.ffi_rustbuffer_free();
        super::names::fill(
            r#"/* ---- Buffers and call status ---- */

static UNIFFI_MAYBE_UNUSED RustBuffer uniffi_buffer_from(const void *data, size_t len) {
    if (len > INT32_MAX) {
        fputs("uniffi: a value is too large to pass to Rust\n", stderr);
        abort();
    }
    ForeignBytes bytes;
    bytes.len = (int32_t)len;
    bytes.data = (const uint8_t *)data;
    RustCallStatus status = {0};
    RustBuffer buffer = @from_bytes@(bytes, &status);
    if (status.code != UNIFFI_CALL_SUCCESS) {
        fputs("uniffi: Rust could not allocate a buffer\n", stderr);
        abort();
    }
    return buffer;
}

static UNIFFI_MAYBE_UNUSED void uniffi_buffer_free(RustBuffer buffer) {
    RustCallStatus status = {0};
    @free@(buffer, &status);
}

static UNIFFI_MAYBE_UNUSED ForeignBytes uniffi_borrow_bytes(uniffi_bytes value) {
    if (value.len > INT32_MAX) {
        fputs("uniffi: a byte string is too large to lend to Rust\n", stderr);
        abort();
    }
    ForeignBytes bytes;
    bytes.len = (int32_t)value.len;
    bytes.data = value.data;
    return bytes;
}

typedef void (*uniffi_error_lifter)(RustBuffer, void *, uniffi_string *);

/* Turns a call status into `status` (and `*err`); true when the call succeeded. */
static UNIFFI_MAYBE_UNUSED bool uniffi_check_call(RustCallStatus *call, uniffi_status *status, uniffi_error_lifter lift_error, void *err) {
    switch (call->code) {
        case UNIFFI_CALL_SUCCESS:
            uniffi_status_ok(status);
            return true;
        case UNIFFI_CALL_ERROR: {
            uniffi_string message = {NULL, 0};
            if (lift_error) {
                lift_error(call->error_buf, err, &message);
            } else {
                uniffi_buffer_free(call->error_buf);
                message = uniffi_string_copy("an error the bindings do not expect", 35);
            }
            uniffi_fail(status, UNIFFI_ERROR, message);
            return false;
        }
        case UNIFFI_CALL_UNEXPECTED_ERROR: {
            uniffi_string message = call->error_buf.len
                ? uniffi_string_copy((const char *)call->error_buf.data, (size_t)call->error_buf.len)
                : uniffi_string_copy("Rust panicked", 13);
            uniffi_buffer_free(call->error_buf);
            uniffi_fail(status, UNIFFI_PANIC, message);
            return false;
        }
        case UNIFFI_CALL_CANCELLED:
            uniffi_fail_str(status, UNIFFI_CANCELLED, "the call was cancelled");
            return false;
        default:
            uniffi_fail_str(status, UNIFFI_INTERNAL, "unexpected RustCallStatus code");
            return false;
    }
}

"#,
            &[("free", free.name()), ("from_bytes", from_bytes.name())],
        )
    }

    fn emit_ensure_init(&self) -> String {
        let contract = self.ci.ffi_uniffi_contract_version();
        let mut checks = String::new();
        if !self.config.omit_checksums {
            for (name, expected) in self.ci.iter_checksums() {
                let _ = writeln!(
                    checks,
                    "        if ({name}() != {expected}) {{\n            fputs(\"uniffi: API checksum mismatch in {ns}: rebuild the bindings and the library together\\n\", stderr);\n            abort();\n        }}",
                    ns = self.prefix
                );
            }
        }
        // Components this one uses come first: C may pass one of their callback
        // interfaces to this component before calling into theirs.
        let mut inits: String = self
            .external_namespaces()
            .iter()
            .map(|ns| format!("        {ns}_uniffi_ensure_init();\n"))
            .collect();
        for cb in self.ci.callback_interface_definitions() {
            let _ = writeln!(inits, "        {}_uniffi_init();", self.local(cb.name()));
        }
        for obj in self.ci.object_definitions() {
            if obj.has_callback_interface() {
                let _ = writeln!(inits, "        {}_uniffi_init();", self.local(obj.name()));
            }
        }
        format!(
            "void {p}_uniffi_ensure_init(void) {{\n    static uniffi_mutex mutex = UNIFFI_MUTEX_INIT;\n    static volatile int initialized = 0;\n    if (initialized) {{\n        return;\n    }}\n    uniffi_mutex_lock(&mutex);\n    if (!initialized) {{\n        if ({contract}() != {version}) {{\n            fputs(\"uniffi: contract version mismatch in {p}: rebuild the bindings and the library together\\n\", stderr);\n            abort();\n        }}\n{checks}{inits}        initialized = 1;\n    }}\n    uniffi_mutex_unlock(&mutex);\n}}\n\n",
            p = self.prefix,
            contract = contract.name(),
            version = self.ci.uniffi_contract_version(),
        )
    }
}
